import{_ as e,o as r,c as n,aj as i}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Rendering strategies in Angular","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/routing/rendering-strategies.md","filePath":"en/guide/routing/rendering-strategies.md"}'),a={name:"en/guide/routing/rendering-strategies.md"};function s(l,t,o,d,g,h){return r(),n("div",null,t[0]||(t[0]=[i('<h1 id="rendering-strategies-in-angular" tabindex="-1">Rendering strategies in Angular <a class="header-anchor" href="#rendering-strategies-in-angular" aria-label="Permalink to &quot;Rendering strategies in Angular&quot;">​</a></h1><p>This guide helps you choose the right rendering strategy for different parts of your Angular application.</p><h2 id="what-are-rendering-strategies" tabindex="-1">What are rendering strategies? <a class="header-anchor" href="#what-are-rendering-strategies" aria-label="Permalink to &quot;What are rendering strategies?&quot;">​</a></h2><p>Rendering strategies determine when and where your Angular application&#39;s HTML content is generated. Each strategy offers different trade-offs between initial page load performance, interactivity, SEO capabilities, and server resource usage.</p><p>Angular supports three primary rendering strategies:</p><ul><li><strong>Client-Side Rendering (CSR)</strong> - Content is rendered entirely in the browser</li><li><strong>Static Site Generation (SSG/Prerendering)</strong> - Content is pre-rendered at build time</li><li><strong>Server-Side Rendering (SSR)</strong> - Content is rendered on the server for the initial request for a route</li></ul><h2 id="client-side-rendering-csr" tabindex="-1">Client-Side Rendering (CSR) <a class="header-anchor" href="#client-side-rendering-csr" aria-label="Permalink to &quot;Client-Side Rendering (CSR)&quot;">​</a></h2><p><strong>CSR is Angular&#39;s default.</strong> Content renders entirely in the browser after JavaScript loads.</p><h3 id="when-to-use-csr" tabindex="-1">When to use CSR <a class="header-anchor" href="#when-to-use-csr" aria-label="Permalink to &quot;When to use CSR&quot;">​</a></h3><p>✅ It can be a good fit for:</p><ul><li>Interactive applications (dashboards, admin panels)</li><li>Real-time applications</li><li>Internal tools where SEO doesn&#39;t matter</li><li>Single-page applications with complex client-side state</li></ul><p>❌ When possible, consider avoiding it for:</p><ul><li>Public-facing content that needs SEO</li><li>Pages where initial load performance is critical</li></ul><h3 id="csr-trade-offs" tabindex="-1">CSR trade-offs <a class="header-anchor" href="#csr-trade-offs" aria-label="Permalink to &quot;CSR trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SEO</strong></td><td style="text-align:left;">Poor - content not visible to crawlers until JS executes</td></tr><tr><td style="text-align:left;"><strong>Initial load</strong></td><td style="text-align:left;">Slower - must download and execute JavaScript first</td></tr><tr><td style="text-align:left;"><strong>Interactivity</strong></td><td style="text-align:left;">Immediate once loaded</td></tr><tr><td style="text-align:left;"><strong>Server needs</strong></td><td style="text-align:left;">Minimal outside of some configuration</td></tr><tr><td style="text-align:left;"><strong>Complexity</strong></td><td style="text-align:left;">Simplest because it works with minimum configuration</td></tr></tbody></table><h2 id="static-site-generation-ssg-prerendering" tabindex="-1">Static Site Generation (SSG/Prerendering) <a class="header-anchor" href="#static-site-generation-ssg-prerendering" aria-label="Permalink to &quot;Static Site Generation (SSG/Prerendering)&quot;">​</a></h2><p><strong>SSG pre-renders pages at build time</strong> into static HTML files. The server sends pre-built HTML for the initial page load. After hydration, your app runs entirely in the browser like a traditional SPA - subsequent navigation, route changes, and API calls all happen client-side without server rendering.</p><h3 id="when-to-use-ssg" tabindex="-1">When to use SSG <a class="header-anchor" href="#when-to-use-ssg" aria-label="Permalink to &quot;When to use SSG&quot;">​</a></h3><p>✅ It can be a good fit for:</p><ul><li>Marketing pages and landing pages</li><li>Blog posts and documentation</li><li>Product catalogs with stable content</li><li>Content that doesn&#39;t change per-user</li></ul><p>❌ When possible, consider avoiding it for:</p><ul><li>User-specific content</li><li>Frequently changing data</li><li>Real-time information</li></ul><h3 id="ssg-trade-offs" tabindex="-1">SSG trade-offs <a class="header-anchor" href="#ssg-trade-offs" aria-label="Permalink to &quot;SSG trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SEO</strong></td><td style="text-align:left;">Excellent - full HTML available immediately</td></tr><tr><td style="text-align:left;"><strong>Initial load</strong></td><td style="text-align:left;">Fastest - pre-generated HTML</td></tr><tr><td style="text-align:left;"><strong>Interactivity</strong></td><td style="text-align:left;">After hydration completes</td></tr><tr><td style="text-align:left;"><strong>Server needs</strong></td><td style="text-align:left;">None for serving (CDN-friendly)</td></tr><tr><td style="text-align:left;"><strong>Build time</strong></td><td style="text-align:left;">Longer - generates all pages upfront</td></tr><tr><td style="text-align:left;"><strong>Content updates</strong></td><td style="text-align:left;">Requires rebuild and redeploy</td></tr></tbody></table><p>📖 <strong>Implementation:</strong> See <a href="/en/guide/ssr#customizing-build-time-prerendering-ssg">Customizing build-time prerendering</a> in the SSR guide.</p><h2 id="server-side-rendering-ssr" tabindex="-1">Server-Side Rendering (SSR) <a class="header-anchor" href="#server-side-rendering-ssr" aria-label="Permalink to &quot;Server-Side Rendering (SSR)&quot;">​</a></h2><p><strong>SSR generates HTML on the server for the initial request for a route</strong>, providing dynamic content with good SEO. The server renders HTML and sends it to the client.</p><p>Once the client renders the page, Angular <a href="/en/guide/hydration#what-is-hydration">hydrates</a> the app and it then runs entirely in the browser like a traditional SPA - subsequent navigation, route changes, and API calls all happen client-side without additional server rendering.</p><h3 id="when-to-use-ssr" tabindex="-1">When to use SSR <a class="header-anchor" href="#when-to-use-ssr" aria-label="Permalink to &quot;When to use SSR&quot;">​</a></h3><p>✅ It can be a good fit for:</p><ul><li>E-commerce product pages (dynamic pricing/inventory)</li><li>News sites and social media feeds</li><li>Personalized content that changes frequently</li></ul><p>❌ When possible, consider avoiding it for:</p><ul><li>Static content (use SSG instead)</li><li>When server costs are a concern</li></ul><h3 id="ssr-trade-offs" tabindex="-1">SSR trade-offs <a class="header-anchor" href="#ssr-trade-offs" aria-label="Permalink to &quot;SSR trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SEO</strong></td><td style="text-align:left;">Excellent - full HTML for crawlers</td></tr><tr><td style="text-align:left;"><strong>Initial load</strong></td><td style="text-align:left;">Fast - immediate content visibility</td></tr><tr><td style="text-align:left;"><strong>Interactivity</strong></td><td style="text-align:left;">Delayed until hydration</td></tr><tr><td style="text-align:left;"><strong>Server needs</strong></td><td style="text-align:left;">Requires server</td></tr><tr><td style="text-align:left;"><strong>Personalization</strong></td><td style="text-align:left;">Full access to user context</td></tr><tr><td style="text-align:left;"><strong>Server costs</strong></td><td style="text-align:left;">Higher - renders on the initial request for a route</td></tr></tbody></table><p>📖 <strong>Implementation:</strong> See <a href="/en/guide/ssr#server-routing">Server routing</a> and <a href="/en/guide/ssr#authoring-server-compatible-components">Authoring server-compatible components</a> in the SSR guide.</p><h2 id="choosing-the-right-strategy" tabindex="-1">Choosing the Right Strategy <a class="header-anchor" href="#choosing-the-right-strategy" aria-label="Permalink to &quot;Choosing the Right Strategy&quot;">​</a></h2><h3 id="decision-matrix" tabindex="-1">Decision matrix <a class="header-anchor" href="#decision-matrix" aria-label="Permalink to &quot;Decision matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">If you need...</th><th style="text-align:left;">Use this strategy</th><th style="text-align:left;">Why</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SEO + Static content</strong></td><td style="text-align:left;">SSG</td><td style="text-align:left;">Pre-rendered HTML, fastest load</td></tr><tr><td style="text-align:left;"><strong>SEO + Dynamic content</strong></td><td style="text-align:left;">SSR</td><td style="text-align:left;">Fresh content on the initial request for a route</td></tr><tr><td style="text-align:left;"><strong>No SEO + Interactivity</strong></td><td style="text-align:left;">CSR</td><td style="text-align:left;">Simplest, no server needed</td></tr><tr><td style="text-align:left;"><strong>Mixed requirements</strong></td><td style="text-align:left;">Hybrid</td><td style="text-align:left;">Different strategies per route</td></tr></tbody></table><h2 id="making-ssr-ssg-interactive-with-hydration" tabindex="-1">Making SSR/SSG Interactive with Hydration <a class="header-anchor" href="#making-ssr-ssg-interactive-with-hydration" aria-label="Permalink to &quot;Making SSR/SSG Interactive with Hydration&quot;">​</a></h2><p>When using SSR or SSG, Angular &quot;hydrates&quot; the server-rendered HTML to make it interactive.</p><p><strong>Available strategies:</strong></p><ul><li><strong>Full hydration</strong> - Entire app becomes interactive at once (default)</li><li><strong>Incremental hydration</strong> - Parts become interactive as needed (better performance)</li><li><strong>Event replay</strong> - Captures clicks before hydration completes</li></ul><p>📖 <strong>Learn more:</strong></p><ul><li><a href="/en/guide/hydration">Hydration guide</a> - Complete hydration setup</li><li><a href="/en/guide/incremental-hydration">Incremental hydration</a> - Advanced hydration with <code>@defer</code> blocks</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/en/guide/ssr">Server-Side Rendering</a></li><li><a href="/en/guide/hydration">Hydration</a></li><li><a href="/en/guide/incremental-hydration">Incremental Hydration</a></li></ul>',47)]))}const f=e(a,[["render",s]]);export{u as __pageData,f as default};
